"""rad0036 (VTP42): the prefill governor, one swappable policy (--prefill-governor SPEC)
for which waiting prompts may start prefilling and in what order prefill work is walked.
Replaces rad0034 and rad0035; an empty spec is the engine's own order.
"""
from __future__ import annotations

import re
from bigcherry.patcher import Edit, FilePatch

_GOVERNOR_H = '#pragma once\n/* BigCherry VTP42: the prefill governor, one swappable policy for which waiting prompts may start\n * prefilling and in what order prefill work is walked. --prefill-governor takes a spec,\n * `kind=K;key=value;...`; an empty spec is `arrival`, the engine\'s own behaviour.\n *\n *   arrival  priority, then arrival; no admission limit.\n *   cap      at most max_seqs long prefills run at once.\n *   budget   the prompt tokens left across running prefills stay within factor x the largest\n *            request (ctx limit), and admitting must not outgrow free KV (the whole-recompute\n *            test). A lone prompt always runs. A prompt waiting past age_ms reserves: no other\n *            long prompt is admitted until it fits.\n *\n * A prompt is long while more than long_tokens of it is left (0: one shared step); a short one\n * is never held back by any kind or reservation, and holds no cap slot.\n *\n * Common keys: order=arrival|remaining (after priority, least prompt left first; prefills behind\n * the first keep one share between them, not one each) and age_ms (under remaining, a prompt\n * still waiting to start after age_ms goes back to arrival order; a running prefill never ages). */\n#include <cstdint>\n#include <cstdlib>\n#include <string>\n\nnamespace rad {\n\nstruct PrefillLoad {\n    int64_t long_seqs = 0;   /* running prefills with more than the long threshold left */\n    int64_t tokens = 0;      /* prompt tokens left across running prefills */\n};\n\nstruct PrefillGovernor {\n    enum Kind : int { kArrival = 0, kCap = 1, kBudget = 2 };\n    enum class Gate { Admit, Wait, Block };   /* Wait: try the next one; Block: reserve */\n\n    int     kind = kArrival;\n    bool    remaining = false;\n    int64_t max_seqs = 0, long_tokens = 0, age_ms = 0;\n    double  factor = 1.5;\n\n    /* false and *err set on an unknown kind, key or value. */\n    static bool parse(const std::string& spec, PrefillGovernor* g, std::string* err) {\n        *g = PrefillGovernor{};\n        size_t at = 0;\n        while (at < spec.size()) {\n            size_t end = spec.find(\';\', at);\n            if (end == std::string::npos) end = spec.size();\n            const std::string kv = spec.substr(at, end - at);\n            at = end + 1;\n            if (kv.empty()) continue;\n            const size_t eq = kv.find(\'=\');\n            const std::string k = kv.substr(0, eq), v = eq == std::string::npos ? "" : kv.substr(eq + 1);\n            char* tail = nullptr;\n            const long long n = std::strtoll(v.c_str(), &tail, 10);\n            const bool num = !v.empty() && *tail == \'\\0\' && n >= 0;\n            if (k == "kind") {\n                if (v == "arrival") g->kind = kArrival;\n                else if (v == "cap") g->kind = kCap;\n                else if (v == "budget") g->kind = kBudget;\n                else return *err = "kind takes arrival, cap or budget, not \'" + v + "\'", false;\n            } else if (k == "order") {\n                if (v != "arrival" && v != "remaining")\n                    return *err = "order takes arrival or remaining, not \'" + v + "\'", false;\n                g->remaining = v == "remaining";\n            } else if (k == "factor") {\n                g->factor = std::strtod(v.c_str(), &tail);\n                if (v.empty() || *tail != \'\\0\' || !(g->factor >= 1.0))\n                    return *err = "factor takes a number of at least 1, not \'" + v + "\'", false;\n            } else if (k == "max_seqs" || k == "long_tokens" || k == "age_ms") {\n                if (!num) return *err = k + " takes a nonnegative integer, not \'" + v + "\'", false;\n                (k == "max_seqs" ? g->max_seqs : k == "long_tokens" ? g->long_tokens : g->age_ms) = n;\n            } else {\n                return *err = "unknown key \'" + k + "\'", false;\n            }\n        }\n        return true;\n    }\n\n    std::string describe() const {\n        static const char* kinds[] = { "arrival", "cap", "budget" };\n        std::string s = std::string("kind=") + kinds[kind] + ";order=" + (remaining ? "remaining" : "arrival");\n        if (kind == kCap) s += ";max_seqs=" + std::to_string(max_seqs);\n        if (kind == kBudget) s += ";factor=" + std::to_string(factor);\n        return s + ";long_tokens=" + std::to_string(long_tokens) + ";age_ms=" + std::to_string(age_ms);\n    }\n\n    /* The walk/queue key after priority (lower first; ties by arrival). Pinned requests (decoding,\n     * preempted, aged) key 0 so arrival decides among them, as in the engine\'s own order. */\n    int64_t key(int64_t left, bool pinned) const { return remaining && !pinned ? left : 0; }\n\n    /* What counts toward a cap slot. */\n    int64_t long_threshold(int64_t shared_tok) const { return long_tokens > 0 ? long_tokens : shared_tok; }\n\n    /* Whether a prompt with `rest` tokens left may start now; `reserved`: an earlier prompt holds a\n     * reservation this step. kv_fits and aged are asked only by budget. */\n    Gate gate(int64_t rest, const PrefillLoad& l, int64_t shared_tok, int64_t max_request,\n              bool reserved, bool aged, bool kv_fits) const {\n        if (rest > 0 && rest <= long_threshold(shared_tok)) return Gate::Admit;\n        if (reserved) return Gate::Wait;\n        if (kind == kCap) return max_seqs <= 0 || l.long_seqs < max_seqs ? Gate::Admit : Gate::Wait;\n        if (kind == kBudget) {\n            if (l.tokens == 0 || (l.tokens + rest <= (int64_t)(factor * (double)max_request) && kv_fits))\n                return Gate::Admit;\n            return aged ? Gate::Block : Gate::Wait;\n        }\n        return Gate::Admit;\n    }\n\n    /* No admission can pass: an overdue recompute must not evict decoders for nothing. */\n    bool full(const PrefillLoad& l, int64_t max_request) const {\n        if (kind == kCap) return max_seqs > 0 && l.long_seqs >= max_seqs;\n        if (kind == kBudget) return l.tokens >= (int64_t)(factor * (double)max_request);\n        return false;\n    }\n};\n\n}  // namespace rad\n'


def _edit(id: str, before: str, after: str, guard: str) -> Edit:
    span = max(4, before.count("\n") + 2)
    return Edit(id=id, anchor=re.escape(before), mode="replace", text=after,
                guard=re.escape(guard), expect_matches=1, max_span_lines=span,
                rationale=("long-anchor: the whole diff hunk is the anchor; " if span > 6 else "")
                + "VTP42: prefill governor hook")


