    FilePatch(path='core/server/iface.h', language="none", description='VTP42 prefill governor', edits=(
        _edit('iface_h-0', 'struct SchedMetrics {\n    int64_t waiting = 0;\n    int64_t running = 0;\n    int64_t preempted = 0;\n    double  kv_util = 0.0;            /* 0..1 of the paged KV pool */\n    /* The paged pools in tokens: how much context fits, which kv_util does not say. */\n', 'struct SchedMetrics {\n    int64_t waiting = 0;\n    int64_t running = 0;\n    int64_t prefilling = 0; /* BC_VTP42_GOV_IFACE_GAUGE */\n    int64_t preempted = 0;\n    double  kv_util = 0.0;            /* 0..1 of the paged KV pool */\n    /* The paged pools in tokens: how much context fits, which kv_util does not say. */\n', 'int64_t prefilling = 0; /* BC_VTP42_GOV_IFACE_GAUGE */'),
        _edit('iface_h-1', '    int64_t draft_verify_depth[MAX_DRAFT_POS + 1] = {};\n    int64_t preemptions = 0;\n    int64_t preempt_forced = 0;       /* --preempt-wait-ms fallback victims */\n    int64_t total_requests = 0;\n    /* Engine steps: one forward pass plus any draft rounds after it. With speculation a step\n     * emits more than one token, so step time cannot be derived from tokens per second. */\n', '    int64_t draft_verify_depth[MAX_DRAFT_POS + 1] = {};\n    int64_t preemptions = 0;\n    int64_t preempt_forced = 0;       /* --preempt-wait-ms fallback victims */\n    int64_t prefill_admissions_deferred = 0; /* BC_VTP42_GOV_IFACE_COUNTER */\n    int64_t total_requests = 0;\n    /* Engine steps: one forward pass plus any draft rounds after it. With speculation a step\n     * emits more than one token, so step time cannot be derived from tokens per second. */\n', 'int64_t prefill_admissions_deferred = 0; /* BC_VTP42_GOV_IFACE_COUNTER */'),
    )),
